insert into public.wisata (id, nama, kategori, tipe, wilayah_id, lokasi, alamat, rating, ulasan, lat, lng, img, banner, ph, ringkas, deskripsi, jam, tiket, link_masjid, musholla, wudhu, galeri, urutan) values
  ('candi-muaro-jambi', 'Kompleks Candi Muaro Jambi', 'Heritage / Cagar Budaya Terbesar', 'Wisata Sejarah & Budaya', 'muaro-jambi', 'Muaro Jambi (30 km dari Kota)', 'Desa Muaro Jambi, Kec. Maro Sebo', 4.8, '1.240', -1.476, 103.668, 'img/wisata/candi-muaro-jambi.jpg', 'img/wisata/candi-muaro-jambi-banner.jpg', 'candi', 'Situs cagar budaya seluas 3.988 hektar dengan fasilitas musholla berwudhu air bersih, persewaan sepeda, dan pemandu lokal berlisensi.', 'Kompleks percandian terluas di Asia Tenggara yang membentang di tepian Sungai Batanghari. Menawarkan wisata sejarah yang tenang, jalur sepeda rindang, serta fasilitas ibadah yang bersih untuk keluarga Muslim.', '07:30-17:30', 'Rp 10.000 / orang', null, '{"status":"Tersedia (Bersih & Nyaman)","teks":"Musholla berada di area pintu masuk utama dan dekat kawasan Candi Tinggi. Terawat rutin dengan pencahayaan alami dan sirkulasi udara yang sejuk.","tag":["Kapasitas ± 40 Jamaah","Mukena & Sajadah Bersih"],"img":"img/wisata/candi-muaro-jambi-musholla.jpg"}'::jsonb, '{"status":"Tersedia (Terpisah Pria & Wanita)","teks":"Area wudhu terpisah antara pria dan wanita dengan sekat privasi yang terjaga. Menggunakan air bersih mengalir dan lantai anti-slip yang aman untuk lansia.","tag":["Air Bersih & Mengalir","Ramah Lansia & Kursi"],"img":"img/wisata/candi-muaro-jambi-wudhu.jpg"}'::jsonb, '[{"img":"img/wisata/candi-muaro-jambi-galeri-1.jpg","label":"Candi Tinggi","ph":"candi"},{"img":"img/wisata/candi-muaro-jambi-galeri-2.jpg","label":"Candi Gumpung","ph":"candi"},{"img":"img/wisata/candi-muaro-jambi-galeri-3.jpg","label":"Kanal Kuno Batanghari","ph":"danau"},{"img":"img/wisata/candi-muaro-jambi-galeri-4.jpg","label":"Jalur Sepeda Rindang","ph":"candi"}]'::jsonb, 0),
  ('gentala-arasy', 'Jembatan Gentala Arasy', 'Landmark & Islamic Heritage', 'Landmark & Wisata Sungai', 'kota-jambi', 'Arab Melayu, Pelayangan', 'Kawasan Jembatan Gentala Arasy, Pelayangan, Kota Jambi', 4.7, '980', -1.5845, 103.6205, 'img/wisata/gentala-arasy.jpg', 'img/wisata/gentala-arasy-banner.jpg', 'sungai', 'Ikon Kota Jambi melintasi Sungai Batanghari dengan Museum Kebudayaan Islam, menara jam penanda waktu sholat, dan sentra ketek perahu.', 'Jembatan pedestrian melintasi Sungai Batanghari menuju menara jam Gentala Arasy di Seberang Kota. Di dalam menara terdapat Museum Kebudayaan Islam, dan di sekitarnya tersedia perahu ketek wisata serta kuliner petang di pelataran sungai.', '', '', null, '{"status":"Tersedia (Musholla Menara)","teks":"Musholla tersedia di kawasan menara Gentala Arasy dengan akses dari pelataran sungai.","tag":["Mukena Tersedia","Dekat Pelataran Sungai"],"img":"img/wisata/gentala-arasy-musholla.jpg"}'::jsonb, '{"status":"Tersedia","teks":"Area wudhu dengan air mengalir di sekitar musholla menara.","tag":["Air Mengalir"],"img":"img/wisata/gentala-arasy-wudhu.jpg"}'::jsonb, '[]'::jsonb, 1),
  ('danau-sipin', 'Danau Sipin & Wisata Ketek', 'Nature & Waterfront', 'Wisata Alam & Keluarga', 'kota-jambi', 'Telanaipura, Jambi Kota', 'Kawasan Danau Sipin, Telanaipura, Kota Jambi', 4.6, '760', -1.602, 103.58, 'img/wisata/danau-sipin.jpg', 'img/wisata/danau-sipin-banner.jpg', 'danau', 'Danau alami di jantung kota, terhubung ke sentra pengrajin batik Jambi seberang, track jogging ramah keluarga, serta perahu wisata halal.', 'Danau alami di jantung Kota Jambi dengan track jogging ramah keluarga dan perahu wisata. Terhubung ke sentra pengrajin batik Jambi di seberang dan menjadi spot favorit menjelang Maghrib.', '', '', null, '{"status":"Tersedia di Sekitar Kawasan","teks":"Musholla dapat dijangkau di sekitar kawasan danau dan sentra batik.","tag":["Ramah Keluarga"],"img":"img/wisata/danau-sipin-musholla.jpg"}'::jsonb, '{"status":"Tersedia","teks":"Fasilitas wudhu tersedia di musholla sekitar kawasan.","tag":["Air Mengalir"],"img":"img/wisata/danau-sipin-wudhu.jpg"}'::jsonb, '[]'::jsonb, 2),
  ('masjid-al-falah-wisata', 'Masjid Agung Al-Falah', 'Islamic Architecture', 'Wisata Religi', 'kota-jambi', 'Legok, Danau Teluk Jambi', 'Jl. Sultan Thaha No.60, Legok, Telanaipura', 4.9, '2.100', -1.5893, 103.614, 'img/wisata/masjid-al-falah.jpg', null, 'masjid', 'Pusat ibadah ikonik tanpa dinding dengan 256 tiang penyangga yang kokoh, angin sejuk alami, dan fasilitas ramah musafir yang buka 24 jam.', null, null, null, 'al-falah', null, null, '[]'::jsonb, 3);
