insert into public.itinerary_contoh (id, hari, mulai, selesai, jenis, judul, sub, tag, catatan, lat, lng, selesai_dikunjungi, urutan) values
  ('s1', 1, '08:00', '09:00', 'kuliner', 'Sarapan Nasi Gemuk Kebun Jahe', 'Restoran Melayu Halal • Citarasa gurih santan dengan sambal khas Jambi & telur rebus.', array['Halal MUI','Ada Musholla']::text[], 'Datang pagi agar tidak kehabisan gulai dori & sambal cabai rawit merah.', -1.605, 103.619, true, 0),
  ('s2', 1, '09:30', '11:45', 'wisata', 'Kompleks Candi Muaro Jambi', 'Eksplorasi Candi Gumpung, Candi Tinggi, dan kanal kuno Batanghari. Tersedia shuttle ramah disabilitas dan lansia.', array['Ramah Muslim','Musholla Nyaman','Sewa Sepeda Listrik']::text[], null, -1.476, 103.668, false, 1),
  ('s3', 1, '12:00', '13:15', 'sholat', 'Sholat Dzuhur Berjamaah di Masjid Agung Al-Falah', 'Ikon "Masjid Seribu Tiang" Jambi yang megah tanpa dinding pembatas, angin alami sejuk dari Sungai Batanghari, serta tempat wudhu luas.', array['Kapasitas 10.000 Jamaah','Tempat Wudhu Luas','Parkir Bus Tersedia']::text[], 'Dianjurkan tiba sebelum adzan untuk mendengarkan tilawah pra-dzuhur.', -1.5893, 103.614, false, 2),
  ('s4', 1, '13:30', '15:00', 'kuliner', 'Makan Siang Gulai Tempoyak RM. Bu Salma', 'Kuliner Tradisional Jambi • Ikan patin sungai segar dimasak fermentasi durian asli, dilengkapi sambal bacang dan lalapan pucuk ubi.', array['QR Halal Terverifikasi','Ruang Makan Ber-AC']::text[], 'Menu favorit: Tempoyak Ikan Baung & Jus Pinang Muda.', -1.596, 103.615, false, 3),
  ('s5', 2, '16:00', '18:00', 'wisata', 'Sunset & Kuliner Petang di Jembatan Gentala Arasy & Danau Sipin', 'Jembatan pedestrian melintasi Sungai Batanghari menuju menara jam Gentala Arasy, lanjut perahu ketek wisata di Danau Sipin menjelang Maghrib.', array['Musholla Menara Tersedia','Spot Foto Sunset Ramah Keluarga']::text[], 'Siapkan kacamata hitam dan nikmati jagung bakar madu halal di pelataran sungai.', -1.5845, 103.6205, false, 4);
